161	fn rerank(recalls: &[RecallResult], cps: &[Checkpoint]) -> Vec<Ranked> {
162	    let by_sha: HashMap<String, String> = cps.iter()
163	        .map(|c| (c.commit_sha.clone(), format!("{} {}", c.commit_sha, c.commit_message)))
164	        .collect();
165	
166	    let mut out: Vec<Ranked> = recalls.iter().map(|r| {
167	        let kind = source_kind(&r.episode.provenance);
168	        let mut ev = vec![Evidence::new(kind, 1.0)];
169	        let sha = commit_of(&r.episode.context);
170	        let backed_by = sha.as_ref().and_then(|k| by_sha.get(k).cloned());
171	        let g = graph_impact();
172	        let (verdict, why) = match sha.as_ref().and_then(|k| cps.iter().find(|c| &c.commit_sha == k)) {
173	            Some(cp) if kind != SourceKind::Verified => agreement(&r.episode.content, cp, &g),
174	            Some(_) => (Agree::Corroborated, "is the commit record".into()),
175	            None => (Agree::Neutral, "no commit context".into()),
176	        };
177	        match verdict {
178	            // Earned corroboration: an independent verified source.
179	            Agree::Corroborated if kind != SourceKind::Verified => {
180	                ev.push(Evidence::new(SourceKind::Verified, 1.0))
181	            }
182	            // Refuted by the ledger: the claim is evidence against itself.
183	            Agree::Contradicted => ev.push(Evidence::new(SourceKind::Unknown, 0.15)),
184	            _ => {}
185	        }
186	        let mut confidence = recall_confidence(&ev);
187	        if verdict == Agree::Contradicted { confidence *= 0.45; }
188	        let scored = r.activation * activation_multiplier(confidence);
189	        let tier = match kind {
190	            SourceKind::Verified => "LEDGER",
191	            SourceKind::UserStated => "INTENT",
192	            SourceKind::Inferred => "infer ",
193	            SourceKind::Unknown => "chat  ",
194	        };
195	        let mut text = r.episode.content.replace('\n', " ");
196	        text.truncate(70);
197	        Ranked { raw: r.activation, scored, confidence, tier, backed_by, text, verdict, why }
198	    }).collect();
199	    out.sort_by(|a, b| b.scored.partial_cmp(&a.scored).unwrap());
200	    let mut seen = HashSet::new();
201	    out.retain(|r| seen.insert(r.text.clone()));
202	    out
203	}
