302	    for line in &cp.diff {
303	        for tok in line.split(|c: char| !c.is_alphanumeric() && c != '_') {
304	            for piece in split_ident(tok) {
305	                if piece.len() > 3 && !STOP.contains(&piece.as_str()) { v.insert(piece); }
306	            }
307	        }
308	    }
309	    for f in &cp.files { for piece in split_ident(f) { if piece.len() > 3 { v.insert(piece); } } }
310	    v
311	}
