338	/// C. DOMAIN LEXICON — hand-written synonym bridges.
339	fn strat_lexicon(claim: &str, cp: &Checkpoint) -> Option<(f32, String)> {
340	    const SYN: &[(&str, &[&str])] = &[
341	        ("retry", &["reattempt", "attempts", "again", "resend"]),
342	        ("guard", &["check", "handle", "prevent", "stopped", "crash"]),
343	        ("empty", &["none", "no", "zero"]),
344	        ("deadline", &["timeout", "budget", "expiry"]),
345	        ("propagate", &["thread", "pass", "visible", "surface"]),
346	        ("caller", &["callers", "whoever", "consumer"]),
347	        ("backoff", &["backing", "delay", "wait"]),
348	    ];
349	    let c = terms(claim);
350	    let ct = terms(&cp.commit_message);
351	    let mut bridged = 0;
352	    let mut how = Vec::new();
353	    for (canon, syns) in SYN {
354	        if ct.contains(*canon) && syns.iter().any(|s| c.contains(*s)) {
355	            bridged += 1; how.push(*canon);
356	        }
357	    }
358	    if bridged >= 2 { Some((bridged as f32, format!("lexicon bridge: {}", how.join("/")))) } else { None }
359	}
