361	/// D. CHARACTER 4-GRAM COSINE — model-free vector similarity, no embedder.
362	fn ngrams(s: &str) -> HashMap<String, f32> {
363	    let t: String = s.to_lowercase().chars().filter(|c| c.is_alphanumeric() || *c==' ').collect();
364	    let ch: Vec<char> = t.chars().collect();
365	    let mut m: HashMap<String, f32> = HashMap::new();
366	    for w in ch.windows(4) { *m.entry(w.iter().collect()).or_insert(0.0) += 1.0; }
367	    m
368	}
369	fn cosine(a: &HashMap<String,f32>, b: &HashMap<String,f32>) -> f32 {
370	    let dot: f32 = a.iter().filter_map(|(k,v)| b.get(k).map(|w| v*w)).sum();
371	    let na: f32 = a.values().map(|v| v*v).sum::<f32>().sqrt();
372	    let nb: f32 = b.values().map(|v| v*v).sum::<f32>().sqrt();
373	    if na*nb == 0.0 { 0.0 } else { dot/(na*nb) }
374	}
375	fn strat_ngram(claim: &str, cp: &Checkpoint) -> Option<(f32, String)> {
376	    let corpus = format!("{} {} {}", cp.commit_message, cp.files.join(" "), cp.diff.join(" "));
377	    let sim = cosine(&ngrams(claim), &ngrams(&corpus));
378	    if sim > 0.10 { Some((sim, format!("4-gram cosine {:.3}", sim))) } else { None }
379	}
