422	/// Lexical-only baseline (v2 behaviour) for comparison.
423	fn agreement_lexical(claim: &str, cp: &Checkpoint) -> Agree {
424	    if terms(claim).intersection(&terms(&cp.commit_message)).count() >= 2 { Agree::Corroborated }
425	    else { Agree::Neutral }
426	}
