428	fn run_eval(cps: &[Checkpoint]) {
429	    let g = graph_impact();
430	    let cases = eval_set();
431	    let find = |sha:&str| cps.iter().find(|c| c.commit_sha==sha).unwrap();
432	
433	    let lex: Vec<(Agree,Agree)> = cases.iter()
434	        .map(|c| (agreement_lexical(c.claim, find(c.sha)), c.truth)).collect();
435	    let fused: Vec<(Agree,Agree)> = cases.iter()
436	        .map(|c| (agreement(c.claim, find(c.sha), &g).0, c.truth)).collect();
437	
438	    println!("── benchmark: {} labelled claim/commit pairs", cases.len());
439	    score("lexical baseline", &lex);
440	    score("fused (graph+pol+MR)", &fused);
441	
442	    println!("\n   misses:");
443	    for (i,c) in cases.iter().enumerate() {
444	        if fused[i].0 != c.truth {
445	            println!("     [{}] got {:?} want {:?} — {} — \"{}\"",
446	                c.sha, fused[i].0, c.truth, c.note,
447	                &c.claim[..c.claim.len().min(56)]);
448	        }
449	    }
450	
451	    // latency
452	    let t0 = std::time::Instant::now();
453	    let iters = 200;
454	    for _ in 0..iters { for c in &cases { let _ = agreement(c.claim, find(c.sha), &g); } }
455	    let per = t0.elapsed().as_micros() as f64 / (iters*cases.len()) as f64;
456	    println!("\n   latency: {:.1} µs per verdict ({} verdicts)", per, iters*cases.len());
457	}
