513	/// Is D's perfect score a plateau or a knife-edge? Sweep the threshold.
514	fn sweep(cps: &[Checkpoint]) {
515	    let g = graph_impact();
516	    let cases = eval_set();
517	    let find = |sha:&str| cps.iter().find(|c| c.commit_sha==sha).unwrap();
518	    println!("\n── threshold sweep: D (4-gram cosine)");
519	    println!("   {:>6} {:>6} {:>7} {:>26}", "thresh", "acc", "para", "note");
520	    for t in [0.04f32,0.06,0.08,0.10,0.12,0.14,0.16,0.20,0.25] {
521	        let preds: Vec<(Agree,Agree)> = cases.iter().map(|c| {
522	            let cp = find(c.sha);
523	            let (mut v,_) = agreement(c.claim, cp, &g);
524	            if v == Agree::Neutral {
525	                let corpus = format!("{} {} {}", cp.commit_message, cp.files.join(" "), cp.diff.join(" "));
526	                if cosine(&ngrams(c.claim), &ngrams(&corpus)) > t { v = Agree::Corroborated; }
527	            }
528	            (v, c.truth)
529	        }).collect();
530	        let acc = preds.iter().filter(|(p,x)| p==x).count() as f32 / preds.len() as f32;
531	        let para: Vec<usize> = cases.iter().enumerate().filter(|(_,c)| c.note=="paraphrase").map(|(i,_)| i).collect();
532	        let pacc = para.iter().filter(|i| preds[**i].0==preds[**i].1).count() as f32/para.len() as f32;
533	        let fp_neutral = cases.iter().enumerate()
534	            .filter(|(i,c)| c.note=="unrelated" && preds[*i].0==Agree::Corroborated).count();
535	        let note = if fp_neutral>0 { format!("{} unrelated wrongly corroborated", fp_neutral) } else { "clean".into() };
536	        println!("   {:>6.2} {:>6.2} {:>6.0}% {:>26}", t, acc, pacc*100.0, note);
537	    }
538	
539	    // A ∪ D
540	    let preds: Vec<(Agree,Agree)> = cases.iter().map(|c| {
541	        let cp = find(c.sha);
542	        let (mut v,_) = agreement(c.claim, cp, &g);
543	        if v == Agree::Neutral && (strat_diff(c.claim,cp).is_some() || strat_ngram(c.claim,cp).is_some()) {
544	            v = Agree::Corroborated;
545	        }
546	        (v, c.truth)
547	    }).collect();
548	    let acc = preds.iter().filter(|(p,x)| p==x).count() as f32 / preds.len() as f32;
549	    println!("\n   A ∪ D (diff OR ngram): acc {:.2}", acc);
550	}
