func (s *ManualCommitStrategy) PrepareCommitMsg(ctx context.Context, commitMsgFile string, source string) error {
	logCtx := logging.WithComponent(ctx, "checkpoint")

	// Skip during rebase, cherry-pick, or revert operations
	// These are replaying existing commits and should not be linked to agent sessions
	if isGitSequenceOperation(ctx) {
		logging.Debug(logCtx, "prepare-commit-msg: skipped during git sequence operation",
			slog.String("strategy", "manual-commit"),
			slog.String("source", source),
		)
		return nil
	}

	// Skip for merge and squash sources
	// These are auto-generated messages - not from Claude sessions
	switch source {
	case "merge", "squash":
		logging.Debug(logCtx, "prepare-commit-msg: skipped for source",
			slog.String("strategy", "manual-commit"),
			slog.String("source", source),
		)
		return nil
	}

	// Handle amend (source="commit") separately: preserve or restore trailer
	if source == "commit" {
		return s.handleAmendCommitMsg(ctx, commitMsgFile)
	}

	_, openRepoSpan := perf.Start(ctx, "open_repository")
	repo, err := OpenRepository(ctx)
	if err != nil {
		openRepoSpan.RecordError(err)
		openRepoSpan.End()
		return nil
	}
	defer repo.Close()
	openRepoSpan.End()

	_, findSessionsSpan := perf.Start(ctx, "find_sessions_for_worktree")
	worktreePath, err := paths.WorktreeRoot(ctx)
	if err != nil {
		findSessionsSpan.RecordError(err)
		findSessionsSpan.End()
		return nil
	}

	// Union of worktree matching and identity matching (the committing
	// process's ancestry) — see findSessionsForCommitLinking; neither
	// suppresses the other. We match by worktree (not BaseCommit) because
	// the user may have made intermediate commits without entering new
	// prompts, causing HEAD to diverge
	sessions, err := s.findSessionsForCommitLinking(ctx, worktreePath)
	if err != nil || len(sessions) == 0 {
		findSessionsSpan.RecordError(err)
		findSessionsSpan.End()
		// No active sessions or error listing - silently skip (hooks must be resilient)
		logging.Debug(logCtx, "prepare-commit-msg: no active sessions",
			slog.String("strategy", "manual-commit"),
			slog.String("source", source),
		)
		return nil
	}
	findSessionsSpan.End()

	s.warnIfAttributionDiverged(ctx, sessions)

	// Fast path: skip content detection for mid-turn agent commits.
	if s.tryAgentCommitFastPath(ctx, commitMsgFile, sessions, source) {
		return nil
	}

	// Check if any session has new content to condense
	_, filterSessionsSpan := perf.Start(ctx, "filter_sessions_with_content")
	sessionsWithContent := s.filterSessionsWithNewContent(ctx, repo, sessions)
	filterSessionsSpan.End()

	if len(sessionsWithContent) == 0 {
		// No new content — no trailer needed
		logging.Debug(logCtx, "prepare-commit-msg: no content to link",
			slog.String("strategy", "manual-commit"),
			slog.String("source", source),
			slog.Int("sessions_found", len(sessions)),
		)
		return nil
	}

	// Read current commit message
	_, readCommitMessageSpan := perf.Start(ctx, "read_commit_message")
	content, err := os.ReadFile(commitMsgFile) //nolint:gosec // commitMsgFile is provided by git hook
	if err != nil {
		readCommitMessageSpan.RecordError(err)
		readCommitMessageSpan.End()
		return nil
	}

	message := string(content)

	// Check if trailer already exists (ParseCheckpoint validates format, so found==true means valid)
	if existingCpID, found := trailers.ParseCheckpoint(message); found {
		readCommitMessageSpan.End()
		// Trailer already exists (e.g., amend) - keep it
		logging.Debug(logCtx, "prepare-commit-msg: trailer already exists",
			slog.String("strategy", "manual-commit"),
			slog.String("source", source),
			slog.String("existing_checkpoint_id", existingCpID.String()),
		)
		return nil
	}
	readCommitMessageSpan.End()

	// Resolve the checkpoint ID and session metadata.
	_, resolveMetadataSpan := perf.Start(ctx, "resolve_session_metadata")
	checkpointID, err := checkpointIDForSessions(ctx, sessionsWithContent)
	if err != nil {
		resolveMetadataSpan.RecordError(err)
		resolveMetadataSpan.End()
		return fmt.Errorf("failed to generate checkpoint ID: %w", err)
	}

	// Determine agent type and last prompt from session
	var agentType types.AgentType
	var lastPrompt string
	if len(sessionsWithContent) > 0 {
		firstSession := sessionsWithContent[0]
		if firstSession.AgentType != "" {
			agentType = firstSession.AgentType
		}
		lastPrompt = s.getLastPrompt(ctx, repo, firstSession)
	}

	// Prepare prompt for display: collapse newlines/whitespace, then truncate (rune-safe)
	displayPrompt := stringutil.TruncateRunes(stringutil.CollapseWhitespace(lastPrompt), 80, "...")

package checkpoint

import (
	"context"

	apicheckpoint "github.com/entireio/cli/api/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
)

// The persistent-checkpoint contract (persisted document types, option types,
// reader/writer interfaces, and the Write request union) lives in the
// api/checkpoint package so storage backends can depend on it without the CLI's
// agent/git machinery. These aliases re-export it under this package so existing
// CLI call sites are unaffected; the git implementation (GitStore, Open, the
// facade, and the ephemeral shadow-branch surface) stays here.
type (
	// Persisted document types.
	Metadata = apicheckpoint.Metadata
	//nolint:revive // CheckpointSummary stutter is accepted (named to avoid conflict with Summary).
	CheckpointSummary = apicheckpoint.CheckpointSummary
	//nolint:revive // CheckpointInfo stutter is accepted (Info is taken by the generic checkpoint.Info type).
	CheckpointInfo   = apicheckpoint.CheckpointInfo
	SessionContent   = apicheckpoint.SessionContent
	SessionFilePaths = apicheckpoint.SessionFilePaths
	TranscriptAsset  = apicheckpoint.TranscriptAsset
	TaskPayload      = apicheckpoint.TaskPayload
	SessionMetrics   = apicheckpoint.SessionMetrics
	Summary          = apicheckpoint.Summary
	LearningsSummary = apicheckpoint.LearningsSummary
	CodeLearning     = apicheckpoint.CodeLearning
	Attribution      = apicheckpoint.Attribution

	// Operation option types.
	WriteOptions               = apicheckpoint.WriteOptions
	UpdateOptions              = apicheckpoint.UpdateOptions
	PrecomputedTranscriptBlobs = apicheckpoint.PrecomputedTranscriptBlobs

	// Reader/writer interfaces and the Write request union. Reads are tiered by
	// scope: CheckpointReader (checkpoint-level) and SessionReader (session-level),
	// composed with Writer into PersistentStore.
	//nolint:revive // CheckpointReader stutter is accepted — marks the checkpoint (vs session) read tier.
	CheckpointReader = apicheckpoint.CheckpointReader
	SessionReader    = apicheckpoint.SessionReader
	PersistentStore  = apicheckpoint.PersistentStore
	Writer           = apicheckpoint.Writer
	WriteRequest     = apicheckpoint.WriteRequest
	// Write request union: session-level (Session, ReservedSession, SessionTranscript,
	// SessionSummary) and checkpoint-level (CheckpointAttribution).
	Session           = apicheckpoint.Session
	ReservedSession   = apicheckpoint.ReservedSession
	SessionTranscript = apicheckpoint.SessionTranscript
	SessionSummary    = apicheckpoint.SessionSummary
	//nolint:revive // CheckpointAttribution stutter is accepted — makes the checkpoint (vs session) tier explicit.
	CheckpointAttribution = apicheckpoint.CheckpointAttribution
)

// Sentinel errors (re-exported so errors.Is keeps working across packages).
var (
	ErrCheckpointNotFound = apicheckpoint.ErrCheckpointNotFound
	ErrNoTranscript       = apicheckpoint.ErrNoTranscript
)

// Contract helper functions, re-exported as thin wrappers rather than vars so
// the facade symbols can't be reassigned by consumers.

func ReadCheckpoint(ctx context.Context, reader CheckpointReader, checkpointID id.CheckpointID) (*CheckpointSummary, error) {
	return apicheckpoint.ReadCheckpoint(ctx, reader, checkpointID) //nolint:wrapcheck // thin re-export of the api/checkpoint helper
}

func ReadLatestSessionContent(ctx context.Context, reader SessionReader, checkpointID id.CheckpointID, summary *CheckpointSummary) (*SessionContent, error) {
	return apicheckpoint.ReadLatestSessionContent(ctx, reader, checkpointID, summary) //nolint:wrapcheck // thin re-export of the api/checkpoint helper
}

func ReadRawSessionLogForCheckpoint(ctx context.Context, reader interface {
	CheckpointReader
	SessionReader
}, checkpointID id.CheckpointID) ([]byte, string, error) {
	return apicheckpoint.ReadRawSessionLogForCheckpoint(ctx, reader, checkpointID) //nolint:wrapcheck // thin re-export of the api/checkpoint helper
}
